// Banco de questoes - Ingles (Unit 8: be going to, should/shouldn't) - 5o ano - prova 23/11
window.BANCO = window.BANCO || {};
window.BANCO.ingles = [
{n:"f",t:"Be going to",q:"Complete: She ___ going to visit her grandma tomorrow.",a:["is","am","are","be"],c:0,e:"Com she (ela) usamos IS: 'She is going to visit her grandma' = Ela vai visitar a avó amanhã. 👵"},
{n:"f",t:"Be going to",q:"Complete: I ___ going to play soccer this afternoon.",a:["is","are","am","be"],c:2,e:"Com I (eu) usamos sempre AM: 'I am going to play soccer' = Eu vou jogar futebol hoje à tarde. ⚽"},
{n:"f",t:"Be going to",q:"Complete: They ___ going to travel to the beach next week.",a:["is","am","was","are"],c:3,e:"Com they (eles) usamos ARE: 'They are going to travel' = Eles vão viajar para a praia semana que vem. 🏖️"},
{n:"f",t:"Be going to",q:"Complete: We ___ going to watch a movie tonight.",a:["am","are","is","be"],c:1,e:"Com we (nós) usamos ARE: 'We are going to watch a movie tonight' = Nós vamos assistir a um filme hoje à noite. 🎬"},
{n:"f",t:"Be going to",q:"Complete: He ___ going to ride his bike after school.",a:["are","am","is","be"],c:2,e:"Com he (ele) usamos IS: 'He is going to ride his bike' = Ele vai andar de bicicleta depois da aula. 🚲"},
{n:"f",t:"Be going to",q:"Complete: You ___ going to love this book!",a:["are","is","am","does"],c:0,e:"Com you (você) usamos ARE: 'You are going to love this book!' = Você vai amar este livro! 📚"},
{n:"f",t:"Be going to",q:"Complete: My dad ___ going to cook pasta tonight.",a:["are","am","were","is"],c:3,e:"My dad = he (ele), então usamos IS: 'My dad is going to cook pasta' = Meu pai vai fazer macarrão hoje à noite. 🍝"},
{n:"f",t:"Be going to",q:"Complete: Look at the dark clouds! It ___ going to rain.",a:["are","is","am","do"],c:1,e:"Com it usamos IS: 'It is going to rain' = Vai chover. As nuvens escuras mostram isso! 🌧️"},
{n:"f",t:"Be going to",q:"Complete: I am going to ___ my room.",a:["clean","cleans","cleaning","cleaned"],c:0,e:"Depois de 'going to' o verbo fica na forma básica, sem -s, -ing ou -ed: 'I am going to clean my room' = Eu vou limpar meu quarto. 🧹"},
{n:"f",t:"Be going to",q:"Complete: She is going to ___ a cake.",a:["makes","make","making","made"],c:1,e:"Depois de 'going to' o verbo fica na forma básica: make. 'She is going to make a cake' = Ela vai fazer um bolo. 🎂"},
{n:"f",t:"Be going to",q:"Complete: They are going to ___ in the pool.",a:["swims","swimming","swim","swam"],c:2,e:"Depois de 'going to' vem o verbo puro: swim. 'They are going to swim in the pool' = Eles vão nadar na piscina. 🏊"},
{n:"f",t:"Be going to",q:"Complete: He is going to ___ TV after dinner.",a:["watches","watching","watched","watch"],c:3,e:"Mesmo com he, depois de 'going to' o verbo NÃO ganha -es: 'He is going to watch TV' = Ele vai ver TV depois do jantar. 📺"},
{n:"f",t:"Be going to",q:"Complete: We are going to ___ our friends on Saturday.",a:["visiting","visit","visits","visited"],c:1,e:"Depois de 'going to' usamos o verbo na forma básica: visit. 'We are going to visit our friends' = Nós vamos visitar nossos amigos no sábado."},
{n:"f",t:"Be going to",q:"O que significa 'I am going to study.'?",a:["Eu estudei.","Eu vou estudar.","Eu estudo todo dia.","Eu estava estudando."],c:1,e:"'Going to' fala de planos para o futuro. 'I am going to study' = Eu vou estudar. 📖"},
{n:"f",t:"Be going to",q:"Qual frase fala de um plano para o FUTURO?",a:["I swam in the pool yesterday.","I swim every single day.","I am going to swim tomorrow.","I was swimming with my friends."],c:2,e:"'Am going to' + 'tomorrow' mostram o futuro: 'I am going to swim tomorrow' = Eu vou nadar amanhã. 🏊"},
{n:"f",t:"Be going to",q:"Qual é a contração (forma curta) de 'I am'?",a:["I's","I'm","Im'","I'am"],c:1,e:"I am vira I'm. 'I'm going to sleep' = Eu vou dormir. O apóstrofo fica no lugar da letra 'a' que sumiu."},
{n:"f",t:"Be going to",q:"Qual é a contração (forma curta) de 'She is'?",a:["Shes'","She'm","She's","She'is"],c:2,e:"She is vira She's. 'She's going to dance' = Ela vai dançar. 💃"},
{n:"f",t:"Be going to",q:"Qual é a contração (forma curta) de 'They are'?",a:["They's","Theyr'","They'am","They're"],c:3,e:"They are vira They're. 'They're going to play' = Eles vão brincar."},
{n:"f",t:"Be going to",q:"Complete: I'm going to ___ a new game.",a:["buy","buys","buying","bought"],c:0,e:"Depois de 'going to' vem o verbo puro: buy. 'I'm going to buy a new game' = Eu vou comprar um jogo novo. 🎮"},
{n:"f",t:"Be going to",q:"Como se diz 'Nós vamos viajar.' em inglês?",a:["We going to travel.","We are going to travel.","We is going to travel.","We are going to travels."],c:1,e:"Precisamos de ARE com we e do verbo puro depois de 'going to': 'We are going to travel.' ✈️"},
{n:"f",t:"Be going to",q:"Qual palavra completa a frase? 'I am going ___ read a book.'",a:["for","at","to","in"],c:2,e:"A estrutura é sempre 'going TO' + verbo: 'I am going to read a book' = Eu vou ler um livro."},
{n:"f",t:"Be going to",q:"Complete: Tom and Ana ___ going to play tennis.",a:["is","am","does","are"],c:3,e:"Tom and Ana são duas pessoas = they (eles), então usamos ARE: 'Tom and Ana are going to play tennis.' 🎾"},
{n:"f",t:"Be going to",q:"Complete: The children ___ going to sing at the party.",a:["are","is","am","was"],c:0,e:"The children (as crianças) = they, então usamos ARE: 'The children are going to sing at the party.' 🎤"},
{n:"f",t:"Be going to",q:"Complete: My cat ___ going to sleep on the sofa.",a:["are","am","is","were"],c:2,e:"My cat = it (um animal), então usamos IS: 'My cat is going to sleep on the sofa.' 🐱"},
{n:"f",t:"Going to: negativa e perguntas",q:"Complete a frase negativa: I ___ going to play video games today.",a:["is not","am not","are not","not am"],c:1,e:"Com I, a negativa é AM NOT: 'I am not going to play video games today' = Eu não vou jogar videogame hoje."},
{n:"f",t:"Going to: negativa e perguntas",q:"Complete a frase negativa: She ___ going to eat pizza.",a:["isn't","aren't","don't","not is"],c:0,e:"Com she, a negativa é ISN'T (is not): 'She isn't going to eat pizza' = Ela não vai comer pizza. 🍕"},
{n:"f",t:"Going to: negativa e perguntas",q:"Complete a frase negativa: They ___ going to go to the park.",a:["isn't","doesn't","aren't","not are"],c:2,e:"Com they, a negativa é AREN'T (are not): 'They aren't going to go to the park' = Eles não vão ao parque."},
{n:"f",t:"Going to: negativa e perguntas",q:"Complete a pergunta: ___ you going to travel this weekend?",a:["Is","Am","Do","Are"],c:3,e:"Na pergunta, o ARE vai para o começo: 'Are you going to travel this weekend?' = Você vai viajar neste fim de semana?"},
{n:"f",t:"Going to: negativa e perguntas",q:"Complete a pergunta: ___ he going to play soccer tomorrow?",a:["Are","Is","Am","Does"],c:1,e:"Com he usamos IS, e na pergunta ele vem primeiro: 'Is he going to play soccer tomorrow?' = Ele vai jogar futebol amanhã?"},
{n:"f",t:"Going to: negativa e perguntas",q:"Responda SIM: 'Are you going to study tonight?'",a:["Yes, I do.","Yes, I am.","Yes, I is.","Yes, you does."],c:1,e:"Se a pergunta usa ARE you, a resposta usa I AM: 'Yes, I am.' = Sim, eu vou."},
{n:"f",t:"Going to: negativa e perguntas",q:"Responda NÃO: 'Is she going to dance?'",a:["No, she doesn't.","No, she aren't.","No, she isn't.","No, she not."],c:2,e:"A pergunta usa IS, então a resposta curta também usa is: 'No, she isn't.' = Não, ela não vai."},
{n:"f",t:"Going to: negativa e perguntas",q:"O que significa 'I'm not going to swim.'?",a:["Eu não vou nadar.","Eu vou nadar.","Eu não nadei.","Eu não sei nadar."],c:0,e:"'I'm not going to' = Eu não vou. Então: 'I'm not going to swim' = Eu não vou nadar."},
{n:"f",t:"Going to: negativa e perguntas",q:"Complete a frase negativa: We ___ going to watch TV tonight.",a:["isn't","am not","don't","aren't"],c:3,e:"Com we, a negativa é AREN'T: 'We aren't going to watch TV tonight' = Nós não vamos ver TV hoje à noite."},
{n:"f",t:"Going to: negativa e perguntas",q:"Complete a pergunta: What ___ you going to eat?",a:["are","is","am","do"],c:0,e:"Com you usamos ARE: 'What are you going to eat?' = O que você vai comer? 🍽️"},
{n:"f",t:"Should / shouldn't",q:"O que significa 'You should drink water.'?",a:["Você vai beber água.","Você deveria beber água.","Você bebeu água.","Você não pode beber água."],c:1,e:"SHOULD = deveria. Usamos para dar conselhos: 'You should drink water' = Você deveria beber água. 💧"},
{n:"f",t:"Should / shouldn't",q:"O que significa 'shouldn't'?",a:["não vai","deveria","não quer","não deveria"],c:3,e:"Shouldn't = should not = não deveria. Ex.: 'You shouldn't run here' = Você não deveria correr aqui."},
{n:"f",t:"Should / shouldn't",q:"'Shouldn't' é a forma curta de:",a:["should no","would not","should not","shall not"],c:2,e:"Shouldn't = should not (não deveria). O 'o' de not some e no lugar dele entra o apóstrofo."},
{n:"f",t:"Should / shouldn't",q:"Complete: You ___ brush your teeth every day.",a:["should","shoulds","should to","are should"],c:0,e:"Usamos apenas SHOULD + verbo: 'You should brush your teeth every day' = Você deveria escovar os dentes todo dia. 🪥"},
{n:"f",t:"Should / shouldn't",q:"Complete: You ___ eat too much candy.",a:["should","should to","shouldn't","shoulds"],c:2,e:"Comer doce demais faz mal, então o conselho é negativo: 'You shouldn't eat too much candy' = Você não deveria comer doce demais. 🍬"},
{n:"f",t:"Should / shouldn't",q:"Complete: She should ___ to bed early.",a:["goes","going","to go","go"],c:3,e:"Depois de 'should' o verbo vem puro, mesmo com she: 'She should go to bed early' = Ela deveria ir para a cama cedo. 😴"},
{n:"f",t:"Should / shouldn't",q:"Complete: He should ___ his hands before lunch.",a:["washes","wash","washing","to wash"],c:1,e:"Should + verbo puro: 'He should wash his hands' = Ele deveria lavar as mãos antes do almoço. 🧼"},
{n:"f",t:"Should / shouldn't",q:"Qual frase com 'should' está correta?",a:["You should study more.","You should to study more.","You shoulds study more.","You should studies more."],c:0,e:"Should nunca ganha -s nem 'to', e o verbo depois dele fica puro: 'You should study more.'"},
{n:"f",t:"Should / shouldn't",q:"Qual é o melhor conselho? 'I'm tired.'",a:["You should run a marathon.","You should go to bed.","You should play all night.","You shouldn't rest."],c:1,e:"Quem está cansado (tired) deveria descansar: 'You should go to bed' = Você deveria ir para a cama."},
{n:"f",t:"Should / shouldn't",q:"Qual é o melhor conselho? 'I'm hungry.'",a:["You should sleep.","You shouldn't eat.","You should eat something.","You should take a shower."],c:2,e:"Hungry = com fome. O conselho certo é: 'You should eat something' = Você deveria comer alguma coisa. 🍎"},
{n:"f",t:"Should / shouldn't",q:"Qual é o melhor conselho? 'I'm thirsty.'",a:["You should drink some water.","You should eat salty chips.","You should run in the sun.","You shouldn't drink anything."],c:0,e:"Thirsty = com sede. 'You should drink some water' = Você deveria beber um pouco de água. 💧"},
{n:"f",t:"Should / shouldn't",q:"Qual é o melhor conselho? 'I have a test tomorrow.'",a:["You should watch TV all night.","You shouldn't study.","You should play video games.","You should study."],c:3,e:"Se tem prova amanhã, o melhor é estudar: 'You should study' = Você deveria estudar. 📝"},
{n:"f",t:"Should / shouldn't",q:"Qual é o melhor conselho? 'I'm cold.'",a:["You should eat ice cream.","You should wear a jacket.","You should open the window.","You should take off your coat."],c:1,e:"Cold = com frio. 'You should wear a jacket' = Você deveria usar uma jaqueta. 🧥"},
{n:"f",t:"Should / shouldn't",q:"Complete: You ___ talk during the test.",a:["should","shoulds","shouldn't","should to"],c:2,e:"Conversar durante a prova não é bom, então usamos SHOULDN'T: 'You shouldn't talk during the test.' 🤫"},
{n:"f",t:"Should / shouldn't",q:"Complete: Children ___ eat fruit and vegetables.",a:["should","shouldn't","should to","shoulds"],c:0,e:"Frutas e verduras fazem bem! 'Children should eat fruit and vegetables' = As crianças deveriam comer frutas e verduras. 🥦"},
{n:"f",t:"Should / shouldn't",q:"Complete: We should ___ the trees and the animals.",a:["protects","protecting","to protect","protect"],c:3,e:"Should + verbo puro: 'We should protect the trees and the animals' = Nós deveríamos proteger as árvores e os animais. 🌳"},
{n:"f",t:"Should / shouldn't",q:"Complete: You shouldn't ___ trash on the street.",a:["throws","throw","throwing","to throw"],c:1,e:"Shouldn't + verbo puro: 'You shouldn't throw trash on the street' = Você não deveria jogar lixo na rua. 🚯"},
{n:"f",t:"Should / shouldn't",q:"O que significa 'should'?",a:["vai","pode","deveria","quer"],c:2,e:"Should = deveria. Usamos should para dar conselhos e dizer o que é bom fazer."},
{n:"f",t:"Should / shouldn't",q:"Qual frase dá um CONSELHO?",a:["I am going to ride my bike.","I rode my bike yesterday.","I like my bike very much.","You should wear a helmet."],c:3,e:"Conselhos usam SHOULD: 'You should wear a helmet' = Você deveria usar capacete. ⛑️"},
{n:"f",t:"Should / shouldn't",q:"Complete: Kids ___ play with fire.",a:["shouldn't","should","shoulds","should to"],c:0,e:"Brincar com fogo é perigoso! 'Kids shouldn't play with fire' = Crianças não deveriam brincar com fogo. 🔥"},
{n:"f",t:"Time expressions",q:"O que significa 'tomorrow'?",a:["ontem","hoje","amanhã","agora"],c:2,e:"Tomorrow = amanhã. Combina com o futuro: 'I'm going to play tomorrow' = Vou brincar amanhã."},
{n:"f",t:"Time expressions",q:"O que significa 'yesterday'?",a:["ontem","amanhã","hoje","depois"],c:0,e:"Yesterday = ontem. Fala do PASSADO, por isso não combina com 'going to'."},
{n:"f",t:"Time expressions",q:"O que significa 'next week'?",a:["semana passada","toda semana","esta semana","próxima semana"],c:3,e:"Next week = na próxima semana (semana que vem). Next = próximo."},
{n:"f",t:"Time expressions",q:"O que significa 'tonight'?",a:["ontem à noite","hoje à noite","toda noite","amanhã de manhã"],c:1,e:"Tonight = hoje à noite. 'We are going to watch a movie tonight' = Vamos ver um filme hoje à noite. 🌙"},
{n:"f",t:"Time expressions",q:"Qual expressão combina com o FUTURO?",a:["yesterday","last week","tomorrow","two days ago"],c:2,e:"Tomorrow (amanhã) é futuro. Yesterday, last week e two days ago falam do passado."},
{n:"f",t:"Time expressions",q:"Complete: I'm going to visit my cousin ___.",a:["last month","next month","yesterday","two weeks ago"],c:1,e:"Com 'going to' falamos do futuro, então usamos 'next month' (no mês que vem)."},
{n:"f",t:"Vocabulary",q:"O que significa 'suitcase'?",a:["mala de viagem","passagem","praia","barraca"],c:0,e:"Suitcase = mala de viagem. 'I'm going to pack my suitcase' = Vou arrumar minha mala. 🧳"},
{n:"f",t:"Vocabulary",q:"O que significa 'beach'?",a:["montanha","praia","piscina","floresta"],c:1,e:"Beach = praia. 'We are going to the beach' = Nós vamos à praia. 🏖️"},
{n:"f",t:"Vocabulary",q:"O que significa 'ticket'?",a:["mala","mapa","passagem ou ingresso","hotel"],c:2,e:"Ticket = passagem (de avião, ônibus) ou ingresso (de cinema, show). 🎟️"},
{n:"f",t:"Vocabulary",q:"O que significa 'healthy'?",a:["doente","cansado","com fome","saudável"],c:3,e:"Healthy = saudável. 'Healthy food' = comida saudável, como frutas e verduras. 🥗"},
{n:"f",t:"Vocabulary",q:"O que significa 'recycle'?",a:["reciclar","desperdiçar","quebrar","comprar"],c:0,e:"Recycle = reciclar. 'We should recycle paper and plastic' = Nós deveríamos reciclar papel e plástico. ♻️"},
{n:"f",t:"Vocabulary",q:"Como se diz 'escovar os dentes' em inglês?",a:["wash your hands","brush your teeth","comb your hair","drink water"],c:1,e:"Brush = escovar e teeth = dentes. 'You should brush your teeth' = Você deveria escovar os dentes. 🪥"},
{n:"f",t:"Vocabulary",q:"O que significa 'trip'?",a:["trem","ingresso","viagem","praia"],c:2,e:"Trip = viagem. 'We are going to take a trip' = Nós vamos fazer uma viagem. ✈️"},
{n:"f",t:"Vocabulary",q:"O que significa 'turn off the lights'?",a:["acender as luzes","trocar as lâmpadas","comprar luzes","apagar as luzes"],c:3,e:"Turn off = desligar/apagar. 'Turn off the lights' = Apague as luzes. Turn on é o contrário (acender). 💡"},
{n:"f",t:"Reading",q:"Leia:\nHi! I'm Leo. Tomorrow I am going to visit my grandma. We are going to make a cake.\n\nO que Leo vai fazer amanhã?",a:["Ir à praia com o pai.","Visitar a avó.","Jogar futebol.","Ir à escola cedo."],c:1,e:"O texto diz 'I am going to visit my grandma' = Eu vou visitar minha avó. E eles vão fazer um bolo juntos! 🎂"},
{n:"f",t:"Reading",q:"Leia:\nAna has a cold. Her mom says: 'You should stay in bed and drink hot tea.'\n\nO que a mãe aconselha?",a:["Tomar sorvete gelado com as amigas da escola.","Correr no parque o dia todo.","Ficar na cama e beber chá quente.","Ir para a escola e brincar."],c:2,e:"'You should stay in bed and drink hot tea' = Você deveria ficar na cama e beber chá quente. 'Has a cold' = está resfriada. 🤧"},
{n:"m",t:"Be going to",q:"Complete com o verbo 'travel': My sister ___ to Rio next month.",a:["are going to travel","is going to travel","is going to travels","going to travel"],c:1,e:"My sister = she, então: IS + going to + verbo puro. 'My sister is going to travel to Rio' = Minha irmã vai viajar para o Rio no mês que vem."},
{n:"m",t:"Be going to",q:"Complete com o verbo 'watch': I ___ a movie tonight.",a:["am going to watch","is going to watch","am going to watching","going to watch"],c:0,e:"Com I usamos AM, e depois de 'going to' o verbo fica puro: 'I am going to watch a movie tonight.' 🍿"},
{n:"m",t:"Be going to",q:"Complete com o verbo 'play': Pedro and I ___ basketball after school.",a:["is going to play","am going to play","are going to plays","are going to play"],c:3,e:"Pedro and I = we (nós), então usamos ARE: 'Pedro and I are going to play basketball.' Cuidado: o I no final não faz virar am! 🏀"},
{n:"m",t:"Be going to",q:"Complete com o verbo 'sleep': The dog ___ in the garden.",a:["are going to sleep","is going to sleep","is going sleep","is going to sleeps"],c:1,e:"The dog = it, então usamos IS. E não pode faltar o 'to': 'The dog is going to sleep in the garden.' 🐶"},
{n:"m",t:"Be going to",q:"Escolha a frase correta para: Ela vai dançar na festa.",a:["She going to dance at the party.","She is going to dances at the party.","She is going to dance at the party.","She are going to dance at the party."],c:2,e:"Precisa de IS (com she) e do verbo puro depois de 'going to': 'She is going to dance at the party.' 💃"},
{n:"m",t:"Be going to",q:"Escolha a frase correta para: Eles vão jogar no parque.",a:["They is going to play in the park.","They are going play in the park.","They going to playing in the park.","They are going to play in the park."],c:3,e:"They + ARE + going TO + verbo puro: 'They are going to play in the park.' Não pode faltar nenhuma parte!"},
{n:"m",t:"Be going to",q:"Coloque as palavras na ordem certa: going / I / to / am / read / a book",a:["I going am to read a book.","I am going to read a book.","I am to going read a book.","I am going read to a book."],c:1,e:"A ordem é: sujeito + am/is/are + going to + verbo. 'I am going to read a book' = Eu vou ler um livro. 📘"},
{n:"m",t:"Be going to",q:"Como se diz 'Eles vão acampar neste fim de semana.' em inglês?",a:["They is going to camp this weekend.","They going to camp this weekend.","They are going to camp this weekend.","They are going to camping this weekend."],c:2,e:"They + ARE + going to + camp (verbo puro): 'They are going to camp this weekend.' ⛺"},
{n:"m",t:"Be going to",q:"Como se diz 'Eu vou fazer minha lição de casa.' em inglês?",a:["I'm going to do my homework.","I'm going to does my homework.","I going to do my homework.","I'm going do my homework."],c:0,e:"I'm = I am. Depois vem 'going to' + do (verbo puro): 'I'm going to do my homework.' ✏️"},
{n:"m",t:"Be going to",q:"Complete com a contração de 'We are': ___ going to visit the museum.",a:["We's","Were","We're","We'am"],c:2,e:"We are vira WE'RE. Cuidado: 'were' (sem apóstrofo) é outra palavra, do passado! 'We're going to visit the museum.' 🏛️"},
{n:"m",t:"Be going to",q:"Complete com a contração de 'He is': ___ going to fly to Bahia.",a:["His","He're","Hes'","He's"],c:3,e:"He is vira HE'S. Cuidado: 'his' quer dizer 'dele', não é contração! 'He's going to fly to Bahia.' ✈️"},
{n:"m",t:"Be going to",q:"Complete: It's sunny! We ___ go to the beach.",a:["are going to","is going to","am going to","are go to"],c:0,e:"Com we usamos ARE going to: 'We are going to go to the beach' = Nós vamos à praia. ☀️"},
{n:"m",t:"Be going to",q:"Complete: My parents ___ buy a new car next year.",a:["is going to","are going to","am going to","are going"],c:1,e:"My parents (meus pais) = they, então usamos ARE going to: 'My parents are going to buy a new car next year.' 🚗"},
{n:"m",t:"Be going to",q:"Complete: Look! The baby ___ cry.",a:["are going to","going to","is going to","is go to"],c:2,e:"The baby = he/she, então usamos IS going to: 'The baby is going to cry' = O bebê vai chorar. 👶"},
{n:"m",t:"Be going to",q:"Complete com o verbo 'bake': Mom ___ cookies this afternoon.",a:["is going to baking","are going to bake","is go to bake","is going to bake"],c:3,e:"Mom = she, então: IS going to + bake (verbo puro). 'Mom is going to bake cookies' = Mamãe vai assar biscoitos hoje à tarde. 🍪"},
{n:"m",t:"Be going to",q:"Qual frase usa 'going to' para falar do futuro?",a:["I am going to call you later.","I called you yesterday.","I call you every day.","I am calling you now."],c:0,e:"'Am going to' + 'later' (mais tarde) mostram um plano para o futuro: 'I am going to call you later' = Vou te ligar mais tarde. 📞"},
{n:"m",t:"Be going to",q:"Complete com o verbo 'help': You and your brother ___ Dad in the garden.",a:["is going to help","are going to help","are going to helps","am going to help"],c:1,e:"You and your brother = vocês, então usamos ARE: 'You and your brother are going to help Dad in the garden.' 🌻"},
{n:"m",t:"Be going to",q:"Complete com o verbo 'go': My friends ___ to the cinema tomorrow.",a:["is going to go","are going go","are going to goes","are going to go"],c:3,e:"My friends = they → ARE going to + go: 'My friends are going to go to the cinema tomorrow.' Parece estranho, mas 'going to go' está certinho! 🎬"},
{n:"m",t:"Be going to",q:"Qual é o verbo certo? 'She's going to ___ her bedroom blue.'",a:["paints","paint","painting","painted"],c:1,e:"Depois de 'going to' o verbo é puro: paint. 'She's going to paint her bedroom blue' = Ela vai pintar o quarto de azul. 🎨"},
{n:"m",t:"Be going to",q:"Complete com o verbo 'pack': Tonight, I ___ my suitcase.",a:["am going to pack","am going to packing","is going to pack","going to pack"],c:0,e:"I + AM + going to + pack: 'I am going to pack my suitcase' = Vou arrumar minha mala hoje à noite. 🧳"},
{n:"m",t:"Be going to",q:"O que significa 'We're going to recycle the bottles.'?",a:["Nós reciclamos as garrafas ontem.","Nós deveríamos reciclar as garrafas.","Nós vamos reciclar as garrafas.","Nós não vamos reciclar as garrafas."],c:2,e:"'We're going to' = Nós vamos. Não confunda com should (deveríamos). 'We're going to recycle the bottles' = Nós vamos reciclar as garrafas. ♻️"},
{n:"m",t:"Be going to",q:"Complete com o verbo 'plant': The students ___ trees next Friday.",a:["is going to plant","are going to planted","are going plant","are going to plant"],c:3,e:"The students = they → ARE going to + plant: 'The students are going to plant trees next Friday.' 🌱"},
{n:"m",t:"Be going to",q:"Complete com o verbo 'tell': Grandpa ___ us a story tonight.",a:["is going to tell","are going to tell","is going to tells","is going tell"],c:0,e:"Grandpa = he → IS going to + tell: 'Grandpa is going to tell us a story tonight' = Vovô vai nos contar uma história hoje à noite. 📖"},
{n:"m",t:"Going to: negativa e perguntas",q:"Transforme em negativa: 'She is going to travel.'",a:["She doesn't going to travel.","She isn't going to travel.","She isn't going to travels.","She not going to travel."],c:1,e:"Para negar, colocamos NOT depois do is: is not = isn't. 'She isn't going to travel' = Ela não vai viajar."},
{n:"m",t:"Going to: negativa e perguntas",q:"Transforme em pergunta: 'They are going to play soccer.'",a:["They are going to play soccer?","Do they going to play soccer?","Are they going to play soccer?","Is they going to play soccer?"],c:2,e:"Na pergunta, o ARE troca de lugar com o sujeito: 'Are they going to play soccer?' = Eles vão jogar futebol? Não usamos 'do'."},
{n:"m",t:"Going to: negativa e perguntas",q:"Responda SIM: 'Are they going to visit the zoo?'",a:["Yes, they are.","Yes, they do.","Yes, they is.","Yes, they going."],c:0,e:"Pergunta com ARE they → resposta 'Yes, they are.' = Sim, eles vão. 🦁"},
{n:"m",t:"Going to: negativa e perguntas",q:"Responda NÃO: 'Are you going to eat pizza?'",a:["No, I don't.","No, you aren't.","No, I isn't.","No, I'm not."],c:3,e:"Quando perguntam sobre você (you), você responde com I: 'No, I'm not.' = Não, eu não vou."},
{n:"m",t:"Going to: negativa e perguntas",q:"Complete: ___ are you going to go on vacation? — To the beach!",a:["When","Where","What","Who"],c:1,e:"A resposta é um lugar (to the beach), então a pergunta começa com WHERE (onde): 'Where are you going to go on vacation?' 🏖️"},
{n:"m",t:"Going to: negativa e perguntas",q:"Complete: ___ are you going to do this weekend? — I'm going to visit my aunt.",a:["Where","Who","What","When"],c:2,e:"A resposta diz o que a pessoa vai fazer, então a pergunta começa com WHAT (o que): 'What are you going to do this weekend?'"},
{n:"m",t:"Going to: negativa e perguntas",q:"Complete: ___ is she going to travel? — Next week.",a:["Where","What","Who","When"],c:3,e:"A resposta é um tempo (next week), então a pergunta começa com WHEN (quando): 'When is she going to travel?' 📅"},
{n:"m",t:"Going to: negativa e perguntas",q:"Complete: I ___ going to watch TV. I'm going to read a book.",a:["am not","is not","are not","do not"],c:0,e:"Com I, a negativa é AM NOT: 'I am not going to watch TV. I'm going to read a book.' = Não vou ver TV, vou ler um livro."},
{n:"m",t:"Going to: negativa e perguntas",q:"Complete: My brothers ___ going to come to the party. They're sick.",a:["isn't","aren't","are","don't"],c:1,e:"Eles estão doentes (sick), então NÃO vão. My brothers = they → AREN'T: 'My brothers aren't going to come to the party.' 🤒"},
{n:"m",t:"Going to: negativa e perguntas",q:"Qual pergunta combina com a resposta 'No, he isn't.'?",a:["Are he going to swim?","Does he going to swim?","Is he going to swim?","Is she going to swim?"],c:2,e:"A resposta fala de HE e usa IS, então a pergunta é 'Is he going to swim?' = Ele vai nadar?"},
{n:"m",t:"Going to: negativa e perguntas",q:"O que significa 'Are you going to help me?'?",a:["Você me ajudou?","Você deveria me ajudar?","Você me ajuda sempre?","Você vai me ajudar?"],c:3,e:"'Are you going to...?' = Você vai...? Então: 'Are you going to help me?' = Você vai me ajudar? 🤝"},
{n:"m",t:"Going to: negativa e perguntas",q:"Complete a resposta: 'Is it going to rain today?' — 'No, it ___.'",a:["isn't","aren't","doesn't","not"],c:0,e:"A pergunta usa IS, então a resposta curta é 'No, it isn't.' = Não, não vai chover. ☀️"},
{n:"m",t:"Should / shouldn't",q:"Transforme em negativa: 'You should eat fast food.'",a:["You don't should eat fast food.","You shouldn't eat fast food.","You shouldn't to eat fast food.","You should don't eat fast food."],c:1,e:"Para negar, juntamos should + not = shouldn't. Não usamos 'don't' com should: 'You shouldn't eat fast food.' 🍔"},
{n:"m",t:"Should / shouldn't",q:"Transforme em pergunta: 'I should wear a coat.'",a:["Do I should wear a coat?","I should wear a coat?","Should I wear a coat?","Should I to wear a coat?"],c:2,e:"Na pergunta, o SHOULD vai para o começo: 'Should I wear a coat?' = Eu deveria usar um casaco? 🧥"},
{n:"m",t:"Should / shouldn't",q:"Responda SIM: 'Should I wash my hands before eating?'",a:["Yes, you should.","Yes, you do.","Yes, I should to.","Yes, you shoulds."],c:0,e:"A pessoa perguntou sobre ela mesma (I), então você responde 'Yes, you should.' = Sim, você deveria. 🧼"},
{n:"m",t:"Should / shouldn't",q:"Responda NÃO: 'Should I play ball near the street?'",a:["No, you don't.","No, you not should.","No, you shouldn't to.","No, you shouldn't."],c:3,e:"Jogar bola perto da rua é perigoso! A resposta curta é 'No, you shouldn't.' = Não, você não deveria. 🚗"},
{n:"m",t:"Should / shouldn't",q:"Escolha a frase correta para: Ele deveria estudar para a prova.",a:["He shoulds study for the test.","He should study for the test.","He should studies for the test.","He should to study for the test."],c:1,e:"Should nunca muda (sem -s) e o verbo depois dele fica puro: 'He should study for the test.' 📚"},
{n:"m",t:"Should / shouldn't",q:"Escolha a frase correta para: Ela não deveria ver TV o dia todo.",a:["She don't should watch TV all day.","She shouldn't watches TV all day.","She shouldn't watch TV all day.","She doesn't should watch TV all day."],c:2,e:"A negativa de should é SHOULDN'T, sem don't/doesn't, e com o verbo puro: 'She shouldn't watch TV all day.' 📺"},
{n:"m",t:"Should / shouldn't",q:"Qual é o melhor conselho? 'I have a toothache.'",a:["You should eat more candy.","You shouldn't tell your mom.","You should go to the beach.","You should go to the dentist."],c:3,e:"Toothache = dor de dente. 'You should go to the dentist' = Você deveria ir ao dentista. 🦷"},
{n:"m",t:"Should / shouldn't",q:"Qual é o melhor conselho? 'My room is very messy.'",a:["You should clean it.","You should buy more toys.","You shouldn't clean it.","You should leave it like that."],c:0,e:"Messy = bagunçado. 'You should clean it' = Você deveria arrumar o quarto. 🧹"},
{n:"m",t:"Should / shouldn't",q:"Qual é o melhor conselho? 'I want to be healthy.'",a:["You should eat chips every day.","You should exercise and eat vegetables.","You shouldn't drink any water.","You should sleep only three hours a night."],c:1,e:"Para ser saudável (healthy): 'You should exercise and eat vegetables' = Você deveria fazer exercícios e comer verduras. 🏃"},
{n:"m",t:"Should / shouldn't",q:"Qual conselho NÃO é bom para cuidar do planeta?",a:["You should recycle paper.","You should turn off the lights.","You should waste water.","You should plant trees."],c:2,e:"Waste = desperdiçar. Desperdiçar água faz mal ao planeta! O certo seria 'You shouldn't waste water.' 🌍"},
{n:"m",t:"Should / shouldn't",q:"Complete: It's very sunny. You ___ wear sunscreen.",a:["shouldn't","should to","shoulds","should"],c:3,e:"Com muito sol, é bom usar protetor solar: 'You should wear sunscreen.' 🧴"},
{n:"m",t:"Should / shouldn't",q:"Complete: You ___ shout in the library.",a:["shouldn't","should","don't should","shouldn't to"],c:0,e:"Na biblioteca precisamos fazer silêncio: 'You shouldn't shout in the library' = Você não deveria gritar na biblioteca. 🤫"},
{n:"m",t:"Should / shouldn't",q:"Complete: You should ___ more water on hot days.",a:["drinks","drink","drinking","to drink"],c:1,e:"Should + verbo puro: 'You should drink more water on hot days' = Você deveria beber mais água nos dias quentes. 💧"},
{n:"m",t:"Should / shouldn't",q:"O que significa 'We should save water.'?",a:["Nós vamos economizar água.","Nós economizamos água.","Nós deveríamos economizar água.","Nós não deveríamos economizar água."],c:2,e:"Should = deveria/deveríamos. Save water = economizar água. 'We should save water' = Nós deveríamos economizar água. 🚰"},
{n:"m",t:"Should / shouldn't",q:"Como se diz 'Você não deveria comer muito açúcar.' em inglês?",a:["You don't should eat a lot of sugar.","You should eat a lot of sugar.","You shouldn't to eat a lot of sugar.","You shouldn't eat a lot of sugar."],c:3,e:"Não deveria = SHOULDN'T, e depois vem o verbo puro (sem to): 'You shouldn't eat a lot of sugar.'"},
{n:"m",t:"Should / shouldn't",q:"Como se diz 'Você deveria ler mais livros.' em inglês?",a:["You should read more books.","You should to read more books.","You shoulds read more books.","You are should read more books."],c:0,e:"Deveria = SHOULD, sem 'to', sem -s e sem 'are': 'You should read more books.' 📚"},
{n:"m",t:"Should / shouldn't",q:"Complete: Anna is sick. She ___ go to school today.",a:["should","shouldn't","shoulds","doesn't should"],c:1,e:"Quem está doente (sick) deve descansar: 'She shouldn't go to school today' = Ela não deveria ir à escola hoje. 🤒"},
{n:"m",t:"Should / shouldn't",q:"Complete: ___ I take an umbrella? — Yes, you should. It's raining.",a:["Do","Am","Should","Shoulds"],c:2,e:"A resposta usa should, então a pergunta também: 'Should I take an umbrella?' = Eu deveria levar um guarda-chuva? ☔"},
{n:"m",t:"Should / shouldn't",q:"Qual é o melhor conselho? 'Pedro always forgets his homework.'",a:["He shouldn't write a list.","He should to write a list.","He should forgets his books.","He should write a list."],c:3,e:"Uma lista ajuda a lembrar das tarefas: 'He should write a list' = Ele deveria fazer uma lista. 📝"},
{n:"m",t:"Should / shouldn't",q:"Complete: Students ___ run in the corridors. It's dangerous.",a:["shouldn't","should","should to","don't should"],c:0,e:"Se é perigoso (dangerous), não devemos fazer: 'Students shouldn't run in the corridors' = Alunos não deveriam correr nos corredores."},
{n:"m",t:"Time expressions",q:"Qual expressão NÃO combina com 'I am going to travel ___'?",a:["tomorrow","yesterday","next week","this summer"],c:1,e:"Yesterday (ontem) é passado e não combina com 'going to', que fala do futuro."},
{n:"m",t:"Time expressions",q:"Complete: We are going to have a party ___.",a:["last Saturday","yesterday","next Saturday","two days ago"],c:2,e:"'Going to' fala do futuro, então usamos 'next Saturday' (no próximo sábado). 🎉"},
{n:"m",t:"Time expressions",q:"Qual frase usa a expressão de tempo corretamente?",a:["I'm going to call you yesterday.","I called you tomorrow.","I'm going to call you last night.","I'm going to call you later."],c:3,e:"Later (mais tarde) é futuro e combina com 'going to'. Yesterday e last night são passado."},
{n:"m",t:"Time expressions",q:"O que significa 'next year'?",a:["no próximo ano","no ano passado","este ano","todo ano"],c:0,e:"Next year = no próximo ano (ano que vem). 'I'm going to be 11 next year' = Vou fazer 11 anos no ano que vem. 🎂"},
{n:"m",t:"Time expressions",q:"Complete: Sofia ___ her grandma yesterday, and she is going to visit her again tomorrow.",a:["is going to visit","visited","visits","visiting"],c:1,e:"Yesterday (ontem) pede o passado: visited. 'Sofia visited her grandma yesterday' = Sofia visitou a avó ontem."},
{n:"m",t:"Vocabulary",q:"Complete: We are going to sleep in a tent. We are going ___!",a:["shopping","swimming","camping","skating"],c:2,e:"Dormir em barraca (tent) é acampar: go camping. 'We are going camping!' = Nós vamos acampar! ⛺"},
{n:"m",t:"Vocabulary",q:"Complete: Don't forget to ___ your suitcase before the trip!",a:["cook","wash","read","pack"],c:3,e:"Pack = arrumar/fazer (a mala). 'Pack your suitcase' = Arrume sua mala. 🧳"},
{n:"m",t:"Vocabulary",q:"Complete: You should ___ your hands before you eat.",a:["wash","brush","comb","cut"],c:0,e:"Wash = lavar. 'Wash your hands' = lave as mãos. Brush (escovar) é para os dentes ou o cabelo. 🧼"},
{n:"m",t:"Vocabulary",q:"Complete: To save energy, you should ___ the lights when you leave the room.",a:["turn on","turn off","buy","break"],c:1,e:"Turn off = apagar/desligar. Apagar as luzes ao sair do quarto economiza energia. 💡"},
{n:"m",t:"Vocabulary",q:"Onde podemos 'swim in the sea and build sandcastles'?",a:["at the library","in the desert","at the beach","on a mountain"],c:2,e:"Nadar no mar e fazer castelos de areia (sandcastles) a gente faz na praia: at the beach. 🏖️"},
{n:"m",t:"Vocabulary",q:"O que significa 'healthy food'?",a:["comida rápida","comida estragada","comida doce","comida saudável"],c:3,e:"Healthy = saudável. Healthy food = comida saudável, como frutas, verduras e arroz com feijão. 🥗"},
{n:"m",t:"Reading",q:"Leia:\nNext summer, Lucas and his family are going to travel to Salvador. They are going to swim in the sea and eat acarajé.\n\nPara onde a família de Lucas vai viajar?",a:["Para o Rio.","Para Salvador.","Para a montanha.","Para o exterior."],c:1,e:"O texto diz 'They are going to travel to Salvador' = Eles vão viajar para Salvador. 🌊"},
{n:"m",t:"Reading",q:"Leia:\nMia wants to be healthy. Her doctor says: 'You should eat fruit, drink water and sleep well. You shouldn't eat a lot of candy.'\n\nO que Mia NÃO deveria fazer?",a:["Comer muitos doces.","Beber água.","Comer frutas.","Dormir bem todas as noites."],c:0,e:"'You shouldn't eat a lot of candy' = Você não deveria comer muitos doces. As outras coisas ela DEVERIA fazer. 🍬"},
{n:"m",t:"Reading",q:"Leia:\nIt's Saturday. Ben isn't going to play soccer today because it's raining. He's going to watch a movie at home.\n\nO que Ben vai fazer hoje?",a:["Jogar futebol com os amigos.","Ir ao parque com o pai.","Assistir a um filme em casa.","Visitar um amigo na escola."],c:2,e:"'He's going to watch a movie at home' = Ele vai assistir a um filme em casa. Ele NÃO vai jogar futebol porque está chovendo. 🎬"},
{n:"m",t:"Reading",q:"Leia:\nOur class is going to clean the school garden next Friday. We are going to pick up trash and plant flowers.\n\nQuando a turma vai limpar o jardim?",a:["Na sexta-feira passada.","No próximo sábado à tarde.","Hoje de manhã.","Na próxima sexta-feira."],c:3,e:"'Next Friday' = na próxima sexta-feira. Next indica o futuro! 🌷"},
{n:"d",t:"Be going to",q:"Encontre o ERRO: 'She is going to plays the piano tomorrow.'",a:["'is' deveria ser 'are'","'plays' deveria ser 'play'","'going' deveria ser 'go'","'tomorrow' deveria ser 'yesterday'"],c:1,e:"Depois de 'going to' o verbo fica puro, sem -s: 'She is going to play the piano tomorrow.' 🎹"},
{n:"d",t:"Be going to",q:"Encontre o ERRO: 'They is going to visit the museum.'",a:["'visit' deveria ser 'visits'","'going' deveria ser 'goes'","'is' deveria ser 'are'","'the' deveria ser 'a'"],c:2,e:"Com they usamos ARE: 'They are going to visit the museum' = Eles vão visitar o museu."},
{n:"d",t:"Be going to",q:"Encontre o ERRO: 'I going to eat a sandwich.'",a:["Falta 'is' depois de I","'eat' deveria ser 'eats'","'going' deveria ser 'go'","Falta 'am' depois de I"],c:3,e:"Não pode faltar o verbo to be! Com I usamos am: 'I am going to eat a sandwich' (ou I'm going to...). 🥪"},
{n:"d",t:"Be going to",q:"Encontre o ERRO: 'We are going to traveling next month.'",a:["'traveling' deveria ser 'travel'","'are' deveria ser 'is'","'next' deveria ser 'last'","'going' deveria ser 'go'"],c:0,e:"Depois de 'going to' não usamos -ing: 'We are going to travel next month.'"},
{n:"d",t:"Be going to",q:"Escolha a frase SEM erro: Minha família vai se mudar para uma casa nova.",a:["My family is going to moves to a new house.","My family is going to move to a new house.","My family going to move to a new house.","My family is going move to a new house."],c:1,e:"Frase completa: My family + IS + going TO + move (verbo puro). 'My family is going to move to a new house.' 🏠"},
{n:"d",t:"Be going to",q:"Escolha a frase SEM erro: Todo mundo vai trazer um lanche.",a:["Everybody are going to bring a snack.","Everybody is going to brings a snack.","Everybody is going to bring a snack.","Everybody going to bring a snack."],c:2,e:"Everybody (todo mundo) parece plural, mas usa IS, como he/she: 'Everybody is going to bring a snack.' 🍎"},
{n:"d",t:"Be going to",q:"Escolha a frase SEM erro: Sara e o irmão dela vão nadar.",a:["Sara and her brother is going to swim.","Sara and her brother are going to swimming.","Sara and her brother going to swim.","Sara and her brother are going to swim."],c:3,e:"Sara and her brother = they (duas pessoas) → ARE going to + swim: 'Sara and her brother are going to swim.' 🏊"},
{n:"d",t:"Be going to",q:"Complete com o verbo 'have': The weather is beautiful! We ___ a picnic in the park.",a:["are going to have","is going to have","are going to having","are going have"],c:0,e:"We + ARE + going to + have: 'We are going to have a picnic in the park' = Vamos fazer um piquenique no parque. 🧺"},
{n:"d",t:"Be going to",q:"O menino está correndo e não vê a pedra no caminho. O que vai acontecer?",a:["He's going to falls.","He's going to fall.","He going to fall.","He are going to fall."],c:1,e:"Quando dá para ver que algo vai acontecer, usamos 'going to': 'He's going to fall' = Ele vai cair! 😮"},
{n:"d",t:"Be going to",q:"Complete com o verbo 'drop': Be careful! You ___ the glasses!",a:["is going to drop","are going to dropping","are going to drop","going to drop"],c:2,e:"You + ARE + going to + drop (verbo puro): 'You are going to drop the glasses!' = Você vai derrubar os copos!"},
{n:"d",t:"Be going to",q:"Qual alternativa completa as DUAS frases?\n'I ___ going to swim.'\n'You ___ going to run.'",a:["is / are","am / is","are / am","am / are"],c:3,e:"Com I usamos AM e com you usamos ARE: 'I am going to swim. You are going to run.'"},
{n:"d",t:"Be going to",q:"Qual alternativa completa as DUAS frases?\n'Lucas ___ going to read.'\n'Lucas and Bia ___ going to draw.'",a:["is / are","are / is","is / is","am / are"],c:0,e:"Lucas sozinho = he → IS. Lucas and Bia = they → ARE. 'Lucas is going to read. Lucas and Bia are going to draw.' ✏️"},
{n:"d",t:"Be going to",q:"Qual frase tem o MESMO sentido de 'Ela planeja ir ao cinema amanhã'?",a:["She went to the cinema with her friends yesterday.","She is going to go to the cinema tomorrow.","She goes to the cinema every day.","She should go to the cinema tomorrow."],c:1,e:"Plano para o futuro = going to: 'She is going to go to the cinema tomorrow.' 'Should' seria um conselho, não um plano. 🎬"},
{n:"d",t:"Be going to",q:"Complete com o verbo 'make': My friends and I ___ a video for the school project.",a:["am going to make","is going to make","are going to make","are going to makes"],c:2,e:"My friends and I = we (nós) → ARE going to + make: 'My friends and I are going to make a video.' Não use am só porque a frase tem I! 🎥"},
{n:"d",t:"Be going to",q:"Encontre o ERRO: 'He's going to studies for the test.'",a:["'He's' deveria ser 'He're'","'going' deveria ser 'goes'","'the' deveria ser 'a'","'studies' deveria ser 'study'"],c:3,e:"Depois de 'going to' vem o verbo puro: 'He's going to study for the test.' 📚"},
{n:"d",t:"Be going to",q:"Encontre o ERRO: 'You is going to love the beach!'",a:["'is' deveria ser 'are'","'love' deveria ser 'loves'","'going' deveria ser 'go'","'the' deveria ser 'a'"],c:0,e:"Com you usamos sempre ARE: 'You are going to love the beach!' 🏖️"},
{n:"d",t:"Be going to",q:"Ordene as palavras: to / going / are / the / We / clean / park",a:["We going are to clean the park.","We are going to clean the park.","We are to going clean the park.","We are going clean to the park."],c:1,e:"Ordem certa: We + are + going to + clean + the park. 'We are going to clean the park' = Vamos limpar o parque. 🌳"},
{n:"d",t:"Be going to",q:"Qual destas frases sobre empinar pipa está ERRADA?",a:["I am going to fly a kite.","They are going to fly a kite.","He are going to fly a kite.","She is going to fly a kite."],c:2,e:"Com he usamos IS, não are. O certo é 'He is going to fly a kite' = Ele vai empinar pipa. 🪁"},
{n:"d",t:"Be going to",q:"Qual destas frases sobre o almoço está ERRADA?",a:["We are going to eat lunch.","You are going to eat lunch.","Dad is going to eat lunch.","We are going to eats lunch."],c:3,e:"Depois de 'going to' o verbo não ganha -s: o certo é 'We are going to eat lunch.' 🍽️"},
{n:"d",t:"Be going to",q:"Complete com o verbo 'stay': My cousins ___ at our house this weekend.",a:["are going to stay","is going to stay","are going to stays","are going stay"],c:0,e:"My cousins (meus primos) = they → ARE going to + stay: 'My cousins are going to stay at our house this weekend.'"},
{n:"d",t:"Be going to",q:"Escolha a frase com a contração CORRETA:",a:["Their going to bake cookies.","They're going to bake cookies.","There going to bake cookies.","They'are going to bake cookies."],c:1,e:"They are = THEY'RE. Their (deles) e there (lá) têm som parecido, mas são outras palavras! 🍪"},
{n:"d",t:"Be going to",q:"Escolha a frase com a contração CORRETA sobre o tempo:",a:["Its going to be a sunny day.","It'is going to be a sunny day.","It's going to be a sunny day.","Is going to be a sunny day."],c:2,e:"It is = IT'S, com apóstrofo: 'It's going to be a sunny day' = Vai ser um dia de sol. ☀️ Sem apóstrofo, 'its' quer dizer 'dele/dela' (de uma coisa)."},
{n:"d",t:"Be going to",q:"Como se diz 'Meu pai vai pintar a casa no mês que vem.' em inglês?",a:["My dad are going to paint the house next month.","My dad is going to paint the house last month.","My dad is going to paints the house next month.","My dad is going to paint the house next month."],c:3,e:"My dad = he → IS going to + paint (puro) + next month (futuro): 'My dad is going to paint the house next month.' 🎨"},
{n:"d",t:"Going to: negativa e perguntas",q:"Transforme em pergunta: 'Your brother is going to play the guitar.'",a:["Does your brother going to play the guitar?","Your brother is going to play the guitar?","Is your brother going to play the guitar?","Are your brother going to play the guitar?"],c:2,e:"Para perguntar, o IS vai para o começo: 'Is your brother going to play the guitar?' 🎸 Não usamos 'does' com going to."},
{n:"d",t:"Going to: negativa e perguntas",q:"Transforme em negativa: 'We are going to watch the game.'",a:["We aren't going to watch the game.","We don't going to watch the game.","We aren't going to watches the game.","We not are going to watch the game."],c:0,e:"Colocamos NOT depois do are: are not = aren't. 'We aren't going to watch the game' = Nós não vamos assistir ao jogo. ⚽"},
{n:"d",t:"Going to: negativa e perguntas",q:"Encontre o ERRO: 'She don't going to come to school tomorrow.'",a:["'come' deveria ser 'comes'","'don't' deveria ser 'isn't'","'school' deveria ser 'schools'","'tomorrow' deveria ser 'yesterday'"],c:1,e:"Com going to, a negativa usa o verbo to be: she → ISN'T. 'She isn't going to come to school tomorrow.'"},
{n:"d",t:"Going to: negativa e perguntas",q:"Encontre o ERRO: 'Is they going to sing at the show?'",a:["'sing' deveria ser 'sings'","'going' deveria ser 'go'","'show' deveria ser 'shows'","'Is' deveria ser 'Are'"],c:3,e:"Com they usamos ARE, também na pergunta: 'Are they going to sing at the show?' 🎤"},
{n:"d",t:"Going to: negativa e perguntas",q:"Responda SIM: 'Are you and your sister going to travel?'",a:["Yes, I am.","Yes, they are.","Yes, we are.","Yes, we do."],c:2,e:"'You and your sister' inclui você! Então a resposta usa WE: 'Yes, we are.' = Sim, nós vamos."},
{n:"d",t:"Going to: negativa e perguntas",q:"Responda NÃO: 'Is your mom going to cook tonight?'",a:["No, she isn't.","No, she doesn't.","No, he isn't.","No, she aren't."],c:0,e:"Your mom = she, e a pergunta usa IS: 'No, she isn't.' = Não, ela não vai. 🍳"},
{n:"d",t:"Going to: negativa e perguntas",q:"Qual pergunta combina com a resposta '— I'm going to go to the beach.'?",a:["When are you going to go?","Who are you going to go with?","Are you going to go?","Where are you going to go?"],c:3,e:"A resposta diz um LUGAR (the beach), então a pergunta começa com WHERE: 'Where are you going to go?' 🏖️"},
{n:"d",t:"Going to: negativa e perguntas",q:"Qual pergunta combina com a resposta '— Next Sunday.'?",a:["Where are they going to play?","When are they going to play?","What are they going to play?","Who is going to play?"],c:1,e:"Next Sunday é um TEMPO (quando), então a pergunta começa com WHEN: 'When are they going to play?' 📅"},
{n:"d",t:"Going to: negativa e perguntas",q:"Qual pergunta combina com a resposta '— A chocolate cake!'?",a:["When are you going to bake?","Where are you going to bake?","What are you going to bake?","Are you going to bake?"],c:2,e:"A resposta diz O QUE vai ser feito, então a pergunta começa com WHAT: 'What are you going to bake?' 🎂"},
{n:"d",t:"Going to: negativa e perguntas",q:"Complete o diálogo:\nA: Are you going to play outside?\nB: No, ___. It's raining.",a:["I'm not","I don't","I isn't","I not am"],c:0,e:"Pergunta com 'Are you' → resposta com 'I'm not': 'No, I'm not. It's raining.' = Não, não vou. Está chovendo. 🌧️"},
{n:"d",t:"Going to: negativa e perguntas",q:"Escolha a pergunta SEM erro: Você vai me ajudar com a lição?",a:["Do you going to help me with the homework?","Are you going to help me with the homework?","Are you going to helps me with the homework?","You are going help me with the homework?"],c:1,e:"Pergunta com going to: ARE + you + going to + help (puro): 'Are you going to help me with the homework?'"},
{n:"d",t:"Going to: negativa e perguntas",q:"Complete: Paulo is sick. He ___ go to the party.",a:["aren't going to","doesn't going to","isn't going","isn't going to"],c:3,e:"Paulo = he → ISN'T going to + go: 'He isn't going to go to the party' = Ele não vai à festa. Não pode faltar o 'to'! 🤒"},
{n:"d",t:"Going to: negativa e perguntas",q:"Faça uma pergunta com WHAT para: 'Lia is going to buy a ticket.'",a:["What is Lia going to buy?","What Lia is going to buy?","What does Lia going to buy?","What is Lia going to buys?"],c:0,e:"Ordem da pergunta: What + is + Lia + going to + buy? = O que a Lia vai comprar? 🎟️"},
{n:"d",t:"Should / shouldn't",q:"Encontre o ERRO: 'You should to eat more vegetables.'",a:["'eat' deveria ser 'eats'","Não se usa 'to' depois de 'should'","'more' deveria ser 'much'","'You' deveria ser 'Your'"],c:1,e:"Depois de should vem o verbo direto, sem 'to': 'You should eat more vegetables.' 🥕"},
{n:"d",t:"Should / shouldn't",q:"Encontre o ERRO: 'She shoulds go to the doctor.'",a:["'go' deveria ser 'goes'","'the' deveria ser 'a'","'shoulds' deveria ser 'should'","'She' deveria ser 'Her'"],c:2,e:"Should nunca ganha -s, nem com he/she/it: 'She should go to the doctor.' 🩺"},
{n:"d",t:"Should / shouldn't",q:"Encontre o ERRO: 'He should drinks more water.'",a:["'should' deveria ser 'shoulds'","'more' deveria ser 'many'","'He' deveria ser 'His'","'drinks' deveria ser 'drink'"],c:3,e:"Depois de should o verbo fica puro: 'He should drink more water.' 💧"},
{n:"d",t:"Should / shouldn't",q:"Encontre o ERRO: 'You don't should play with matches.'",a:["'don't should' deveria ser 'shouldn't'","'play' deveria ser 'plays'","'with' deveria ser 'to'","'matches' deveria ser 'match'"],c:0,e:"A negativa de should é SHOULDN'T (should not), sem don't: 'You shouldn't play with matches.' Matches = fósforos. 🔥"},
{n:"d",t:"Should / shouldn't",q:"Complete o diálogo:\nA: Should I call the teacher?\nB: Yes, ___.",a:["you do","you should","I should to","you shoulds"],c:1,e:"Pergunta com 'Should I...?' → resposta 'Yes, you should.' = Sim, você deveria."},
{n:"d",t:"Should / shouldn't",q:"Complete o diálogo:\nA: Should I eat this old banana? It smells bad.\nB: No, ___.",a:["you don't","you not should","you shouldn't","I don't should"],c:2,e:"Banana velha e com cheiro ruim não deve ser comida! 'No, you shouldn't.' = Não, você não deveria. 🍌"},
{n:"d",t:"Should / shouldn't",q:"Escolha a pergunta SEM erro: Eu devo levar uma jaqueta?",a:["Do I should bring a jacket?","Should I to bring a jacket?","I should bring a jacket?","Should I bring a jacket?"],c:3,e:"Na pergunta, SHOULD vem primeiro, sem 'do' e sem 'to': 'Should I bring a jacket?'"},
{n:"d",t:"Should / shouldn't",q:"Transforme em pergunta: 'We should leave now.'",a:["Should we leave now?","Do we should leave now?","We should leave now?","Should we leaves now?"],c:0,e:"Trocamos de lugar: Should + we + leave? 'Should we leave now?' = Nós deveríamos sair agora?"},
{n:"d",t:"Should / shouldn't",q:"Bia is going to travel to a very cold city. Qual é o melhor conselho?",a:["She should pack only swimsuits.","She should pack warm clothes.","She shouldn't take a coat.","She should wear sandals all day."],c:1,e:"Ela vai para um lugar frio, então: 'She should pack warm clothes' = Ela deveria levar roupas quentes. 🧣"},
{n:"d",t:"Should / shouldn't",q:"Tom is going to run a race tomorrow. Qual é o melhor conselho?",a:["He should stay up all night.","He shouldn't drink any water.","He should sleep well tonight.","He should eat a lot of candy."],c:2,e:"Antes de uma corrida (race), é importante descansar: 'He should sleep well tonight' = Ele deveria dormir bem hoje à noite. 🏃"},
{n:"d",t:"Should / shouldn't",q:"Qual frase usa 'going to' e 'should' CORRETAMENTE?",a:["I'm going to swims, so I should wear sunscreen.","I going to swim, so I should to wear sunscreen.","I'm going to swim, so I shoulds wear sunscreen.","I'm going to swim, so I should wear sunscreen."],c:3,e:"Plano (I'm going to swim) + conselho (I should wear sunscreen). Os dois pedem verbo puro, e não se usa 'to' depois de should. 🏊"},
{n:"d",t:"Should / shouldn't",q:"Complete: It's going to rain. You ___ take an umbrella.",a:["should","shouldn't","should to","are should"],c:0,e:"Se vai chover, o conselho é levar guarda-chuva: 'You should take an umbrella.' ☔"},
{n:"d",t:"Should / shouldn't",q:"Complete: The floor is wet. You ___ run here.",a:["should","don't should","shouldn't","shouldn't to"],c:2,e:"Chão molhado (wet) escorrega! 'You shouldn't run here' = Você não deveria correr aqui. ⚠️"},
{n:"d",t:"Should / shouldn't",q:"Qual é o melhor conselho? 'I always feel tired in class.'",a:["You should play video games at night.","You should go to bed earlier.","You shouldn't sleep at all.","You should drink soda before bed."],c:1,e:"Quem fica cansado na aula precisa dormir mais: 'You should go to bed earlier' = Você deveria ir dormir mais cedo. 😴"},
{n:"d",t:"Should / shouldn't",q:"Qual frase diz que algo NÃO é uma boa ideia?",a:["You should touch the stove.","You're going to touch the stove.","You touched the stove.","You shouldn't touch the stove."],c:3,e:"Shouldn't = não deveria. 'You shouldn't touch the stove' = Você não deveria mexer no fogão. Pode queimar! 🔥"},
{n:"d",t:"Should / shouldn't",q:"Qual destas frases com 'should' está ERRADA?",a:["She should goes home.","She should go home.","They should go home.","We shouldn't go home."],c:0,e:"Depois de should o verbo fica puro, mesmo com she: o certo é 'She should go home.'"},
{n:"d",t:"Should / shouldn't",q:"Qual é a diferença entre 'You should study.' e 'You are going to study.'?",a:["As duas frases dão conselhos e significam a mesma coisa.","A primeira dá um conselho; a segunda fala de um plano.","As duas frases falam de algo que aconteceu no passado.","A primeira é uma pergunta; a segunda é uma ordem."],c:1,e:"Should = conselho (você deveria estudar). Going to = plano para o futuro (você vai estudar)."},
{n:"d",t:"Should / shouldn't",q:"We're going camping in the forest. Qual é o melhor conselho?",a:["You should leave trash in the forest.","You shouldn't take any water.","You should take a flashlight.","You should make a fire inside the tent."],c:2,e:"Na floresta, à noite, fica bem escuro: 'You should take a flashlight' = Vocês deveriam levar uma lanterna. 🔦"},
{n:"d",t:"Should / shouldn't",q:"Responda SIM: 'Should Lucas wear a helmet when he rides his bike?'",a:["Yes, he does.","Yes, he shoulds.","Yes, you should.","Yes, he should."],c:3,e:"A pergunta é sobre Lucas (he), então: 'Yes, he should.' = Sim, ele deveria. 🚲"},
{n:"d",t:"Should / shouldn't",q:"Transforme em negativa: 'Kids should drink soda every day.'",a:["Kids shouldn't drink soda every day.","Kids don't should drink soda every day.","Kids shouldn't drinks soda every day.","Kids should not to drink soda every day."],c:0,e:"Should + not = shouldn't, e o verbo continua puro: 'Kids shouldn't drink soda every day' = Crianças não deveriam beber refrigerante todo dia. 🥤"},
{n:"d",t:"Time expressions",q:"Qual frase está ERRADA por causa da expressão de tempo?",a:["I visited Paris last year.","I'm going to visit Paris last year.","I'm going to visit Paris next year.","I'm going to visit Paris soon."],c:1,e:"Last year (ano passado) é passado e não combina com 'going to'. Com going to usamos next year, soon, tomorrow..."},
{n:"d",t:"Time expressions",q:"Complete: Yesterday I ___ soccer, and tomorrow I ___ basketball.",a:["am going to play / played","play / played","played / am going to play","played / played"],c:2,e:"Yesterday (ontem) pede o passado: played. Tomorrow (amanhã) pede o futuro: am going to play. ⚽🏀"},
{n:"d",t:"Time expressions",q:"Qual expressão completa a frase? 'We are going to have a test ___.'",a:["the day before yesterday","last Monday","two weeks ago","the day after tomorrow"],c:3,e:"The day after tomorrow = depois de amanhã (futuro). The day before yesterday = anteontem (passado)."},
{n:"d",t:"Time expressions",q:"Coloque do MAIS PRÓXIMO para o MAIS DISTANTE no futuro:",a:["tonight → tomorrow → next week → next year","next year → next week → tomorrow → tonight","tomorrow → tonight → next year → next week","next week → tonight → next year → tomorrow"],c:0,e:"Tonight (hoje à noite) vem primeiro, depois tomorrow (amanhã), next week (semana que vem) e next year (ano que vem)."},
{n:"d",t:"Vocabulary",q:"Complete: To get on the plane, you need a ___.",a:["tent","ticket","towel","flashlight"],c:1,e:"Para entrar no avião, você precisa de uma passagem: ticket. ✈️"},
{n:"d",t:"Vocabulary",q:"Qual expressão NÃO combina com hábitos saudáveis?",a:["exercise","vegetables","junk food","sleep well"],c:2,e:"Junk food = comida 'porcaria' (salgadinho, refrigerante, fritura). You shouldn't eat a lot of junk food!"},
{n:"d",t:"Vocabulary",q:"Qual palavra NÃO combina com cuidar do meio ambiente?",a:["recycle","save","protect","waste"],c:3,e:"Waste = desperdiçar. Recycle (reciclar), save (economizar) e protect (proteger) ajudam o planeta. 🌎"},
{n:"d",t:"Vocabulary",q:"Complete: You shouldn't ___ food. Put only what you can eat on your plate.",a:["waste","recycle","pack","brush"],c:0,e:"Waste = desperdiçar. 'You shouldn't waste food' = Você não deveria desperdiçar comida. 🍽️"},
{n:"d",t:"Vocabulary",q:"Complete: We're going to the beach. Don't forget your ___ and sunscreen!",a:["scarf","gloves","swimsuit","boots"],c:2,e:"Swimsuit = roupa de banho (maiô ou sunga). Scarf (cachecol), gloves (luvas) e boots (botas) são para o frio. 👙"},
{n:"d",t:"Vocabulary",q:"O que você faz quando vai 'camping'?",a:["stay in a fancy hotel","go to the mall","ride an elevator","sleep in a tent"],c:3,e:"Go camping = acampar, e quem acampa dorme em uma barraca: sleep in a tent. ⛺"},
{n:"d",t:"Reading",q:"Leia:\nMy name is Julia. This weekend my family and I are going to visit my uncle's farm. I'm going to ride a horse, but my brother isn't going to ride. He's scared!\n\nQuem NÃO vai andar a cavalo?",a:["A Julia.","O irmão da Julia.","O tio da Julia.","Os pais da Julia e o tio."],c:1,e:"O texto diz 'my brother isn't going to ride. He's scared!' = meu irmão não vai andar a cavalo. Ele está com medo! 🐴"},
{n:"d",t:"Reading",q:"Leia:\nDear Tom,\nYou are going to start soccer practice next week. You should drink a lot of water, and you shouldn't forget your shin guards. Have fun!\nCoach Mike\n\nO que o treinador NÃO disse na mensagem?",a:["Beber bastante água.","Não esquecer as caneleiras.","Chegar cedo ao treino.","Divertir-se no treino."],c:2,e:"O treinador falou de água (water), caneleiras (shin guards) e diversão (have fun). Ele não falou nada sobre chegar cedo. ⚽"},
{n:"d",t:"Reading",q:"Leia:\nLeo has a big test on Monday. On Saturday he is going to play video games all day, and on Sunday he is going to go to a party.\n\nQual é o melhor conselho para Leo?",a:["He should play more video games.","He shouldn't study at all.","He should go to two parties.","He should study this weekend."],c:3,e:"Leo tem prova na segunda e não planejou estudar! O melhor conselho: 'He should study this weekend' = Ele deveria estudar neste fim de semana. 📚"},
{n:"d",t:"Reading",q:"Leia:\nNext month, our school is going to have a 'Green Week'. Students are going to recycle paper, plant trees and turn off the lights when they leave the classroom.\n\nQual frase sobre o texto está CORRETA?",a:["Os alunos vão plantar árvores.","Os alunos vão desperdiçar papel.","A Green Week foi no mês passado.","Os alunos vão deixar as luzes acesas."],c:0,e:"O texto diz 'Students are going to plant trees' = Os alunos vão plantar árvores. 🌳 A Green Week vai ser no mês que vem (next month)."},
];
